import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // ============================================================================
  // 1. BUILD GEOMETRY & MATERIAL
  // ============================================================================

  // Create plane geometry (unit square, will scale via config.scale)
  const geometry = new THREE.PlaneGeometry(1, 1);

  // Load the decal texture asynchronously
  let mat = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
    depthWrite: false,
    depthTest: true,
  });

  const mesh = new THREE.Mesh(geometry, mat);

  // Load texture and update material
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      // Create texture node for the material
      const texNode = texture(tex);
      mat.colorNode = texNode;
      mat.needsUpdate = true;
    });
  }

  // ============================================================================
  // 2. APPLY SCENE POSITION & SCALE (adapter will NOT re-apply these)
  // ============================================================================

  if (config.scenePosition) {
    mesh.position.set(
      config.scenePosition.x ?? 0,
      config.scenePosition.y ?? 0,
      config.scenePosition.z ?? 0
    );
  }

  if (config.rotation) {
    mesh.rotation.set(
      config.rotation.x ?? 0,
      config.rotation.y ?? 0,
      config.rotation.z ?? 0
    );
  }

  if (config.scale) {
    mesh.scale.set(
      config.scale.x ?? 1,
      config.scale.y ?? 1,
      config.scale.z ?? 1
    );
  }

  // ============================================================================
  // 3. ADD TEXT CONTENT (headline "Features 2")
  // ============================================================================

  const textContent = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // Find the headline item
  const headlineItem = textContent.find(item => item.role === 'headline');

  if (headlineItem) {
    const textMesh = ctx.fontAtlas.createText(headlineItem.text, {
      fontSize: headlineItem.typography?.fontSize ?? 39,
      color: config.intent?.visualSpec?.colors?.paper ?? '#e8ecf2',
      align: 'center',
    });

    // Position text relative to the plane (slightly forward and centered)
    textMesh.position.z = 0.2;
    textMesh.position.y = 0.15;

    mesh.add(textMesh);
  }

  // ============================================================================
  // 4. SETUP CLEANUP
  // ============================================================================

  mesh.userData.cleanup = () => {
    geometry.dispose();
    mat.dispose();
  };

  return mesh;
}
